"use client";

import * as React from "react";
import { Plus, X } from "lucide-react";
import { useFieldArray, useFormContext, useWatch } from "react-hook-form";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DisclosureHeader } from "@/components/json-form/disclosure";
import type { RenderJsonFormField } from "@/components/json-form/field-renderer";
import {
  AUTO_COLLAPSE_DEPTH,
  CARD_VIRTUALIZE_THRESHOLD,
  LONG_ARRAY_THRESHOLD,
} from "@/components/json-form/json-form-constants";
import { useJsonFormStartsOpen } from "@/components/json-form/open-paths";
import {
  emptyArrayItemFormValue,
  joinJsonFormPath,
  joinJsonSourcePath,
} from "@/components/json-form/path-codec";
import type { JsonFormTextInput } from "@/components/json-form/scalar-control";
import {
  arrayItemSchemaAt,
  canAppendArrayItem,
  canRemoveArrayItem,
  hasDynamicObjectProperties,
  scalarObjectColumns,
  type Schema,
} from "@/components/json-form/schema-model";
import { ArrayTable } from "@/components/json-form/table/array-table";
import { VirtualList } from "@/components/json-form/virtual-list";

export function JsonFormArray({
  name,
  sourcePath,
  schema,
  label,
  textInput,
  className,
  depth,
  renderField,
}: {
  name: string;
  sourcePath: string;
  schema: Schema;
  label: string;
  textInput?: JsonFormTextInput;
  className?: string;
  depth: number;
  renderField: RenderJsonFormField;
}) {
  const { control, getValues, setValue, unregister } = useFormContext();
  const { fields, append, remove } = useFieldArray({ control, name });
  const arrayValue = useWatch({ control, name });
  const renderedFields = React.useMemo(() => {
    if (!Array.isArray(arrayValue)) return fields;
    return arrayValue.map((_, index) => ({
      id: fields[index]?.id ?? `${name}.${index}`,
    }));
  }, [arrayValue, fields, name]);
  const itemSchema = React.useMemo(
    () => arrayItemSchemaAt(schema, 0),
    [schema],
  );
  const isTupleArray = Array.isArray(schema.items);
  const hasDynamicItemProperties = React.useMemo(
    () => hasDynamicObjectProperties(itemSchema),
    [itemSchema],
  );
  const itemSchemaForIndex = React.useCallback(
    (index: number) => arrayItemSchemaAt(schema, index),
    [schema],
  );

  const columns = React.useMemo(
    () =>
      isTupleArray || hasDynamicItemProperties
        ? null
        : scalarObjectColumns(itemSchema),
    [hasDynamicItemProperties, isTupleArray, itemSchema],
  );

  const startsOpen = useJsonFormStartsOpen(
    sourcePath,
    depth < AUTO_COLLAPSE_DEPTH &&
      renderedFields.length <= LONG_ARRAY_THRESHOLD,
  );
  const [open, setOpen] = React.useState(startsOpen);
  const canAddItem = canAppendArrayItem(schema, renderedFields.length);
  const canRemoveItem = canRemoveArrayItem(schema, renderedFields.length);

  const add = React.useCallback(() => {
    const current = getValues(name);
    const nextIndex = Array.isArray(current)
      ? current.length
      : renderedFields.length;
    if (!canAppendArrayItem(schema, nextIndex)) return;
    const nextSchema = arrayItemSchemaAt(schema, nextIndex);
    const nextItem = emptyArrayItemFormValue(nextSchema);
    append(nextItem as never);
    if (Array.isArray(current)) {
      setValue(name, [...current, nextItem], { shouldDirty: true });
    }
    setOpen(true);
  }, [append, getValues, name, renderedFields.length, schema, setValue]);
  const removeAt = React.useCallback(
    (index: number) => {
      const current = getValues(name);
      if (Array.isArray(current)) {
        if (!canRemoveArrayItem(schema, current.length)) return;
        const next = current.slice();
        next.splice(index, 1);
        remove(index);
        setValue(name, next, { shouldDirty: true });
        unregister(`${name}.${next.length}`);
        return;
      }
      if (!canRemoveArrayItem(schema, renderedFields.length)) return;
      remove(index);
    },
    [
      getValues,
      name,
      remove,
      renderedFields.length,
      schema,
      setValue,
      unregister,
    ],
  );

  return (
    <div
      className={cn(
        "bg-background overflow-hidden rounded-lg border shadow-sm",
        className,
      )}
    >
      <DisclosureHeader
        open={open}
        onToggle={() => setOpen((o) => !o)}
        title={label}
        summary={`${renderedFields.length} item${renderedFields.length === 1 ? "" : "s"}`}
        description={schema.description}
        actions={
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={add}
            disabled={!canAddItem}
          >
            <Plus className="size-4" />
            Add
          </Button>
        }
      />
      {open ? (
        <div className={cn("border-t", columns ? "" : "p-3")}>
          {renderedFields.length === 0 ? (
            <p className="text-muted-foreground text-sm">No items.</p>
          ) : columns ? (
            <ArrayTable
              name={name}
              sourcePath={sourcePath}
              fields={renderedFields}
              remove={removeAt}
              canRemove={canRemoveItem}
              columns={columns}
            />
          ) : (
            <ArrayCards
              name={name}
              sourcePath={sourcePath}
              fields={renderedFields}
              remove={removeAt}
              canRemove={canRemoveItem}
              itemSchemaForIndex={itemSchemaForIndex}
              label={label}
              textInput={textInput}
              depth={depth}
              renderField={renderField}
            />
          )}
        </div>
      ) : null}
    </div>
  );
}

interface ArrayCardsProps {
  name: string;
  sourcePath: string;
  fields: { id: string }[];
  remove: (index: number) => void;
  canRemove: boolean;
  itemSchemaForIndex: (index: number) => Schema;
  label: string;
  textInput?: JsonFormTextInput;
  depth: number;
  renderField: RenderJsonFormField;
}

function ArrayCards({
  name,
  sourcePath,
  fields,
  remove,
  canRemove,
  itemSchemaForIndex,
  label,
  textInput,
  depth,
  renderField,
}: ArrayCardsProps) {
  const renderCard = React.useCallback(
    (index: number) => (
      <ArrayCard
        name={name}
        sourcePath={sourcePath}
        index={index}
        remove={remove}
        canRemove={canRemove}
        itemSchema={itemSchemaForIndex(index)}
        label={label}
        textInput={textInput}
        depth={depth}
        renderField={renderField}
      />
    ),
    [
      name,
      sourcePath,
      remove,
      canRemove,
      itemSchemaForIndex,
      label,
      textInput,
      depth,
      renderField,
    ],
  );

  if (fields.length > CARD_VIRTUALIZE_THRESHOLD) {
    return (
      <VirtualList
        fields={fields}
        estimateSize={64}
        renderItem={renderCard}
        gap={8}
      />
    );
  }

  return (
    <div className="space-y-2">
      {fields.map((entry, index) => (
        <React.Fragment key={entry.id}>{renderCard(index)}</React.Fragment>
      ))}
    </div>
  );
}

const ArrayCard = React.memo(function ArrayCard({
  name,
  sourcePath,
  index,
  remove,
  canRemove,
  itemSchema,
  label,
  textInput,
  depth,
  renderField,
}: {
  name: string;
  sourcePath: string;
  index: number;
  remove: (index: number) => void;
  canRemove: boolean;
  itemSchema: Schema;
  label: string;
  textInput?: JsonFormTextInput;
  depth: number;
  renderField: RenderJsonFormField;
}) {
  return (
    <div className="flex items-start gap-2">
      <div className="min-w-0 flex-1">
        {renderField({
          name: joinJsonFormPath(name, index),
          sourcePath: joinJsonSourcePath(sourcePath, index),
          schema: itemSchema,
          label: `${label} ${index + 1}`,
          textInput,
          depth: depth + 1,
        })}
      </div>
      <Button
        type="button"
        size="icon"
        variant="ghost"
        className="text-muted-foreground hover:border-border hover:text-destructive mt-1 border-transparent hover:bg-transparent"
        onClick={() => remove(index)}
        aria-label="Remove item"
        disabled={!canRemove}
      >
        <X className="size-4" />
      </Button>
    </div>
  );
});

"use client";

import * as React from "react";
import { ChevronRight } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/**
 * Wraps a label element so a field description shows as a hover tooltip on the
 * label itself rather than a body-text block that changes row height.
 */
export function WithDescription({
  text,
  children,
}: {
  text?: string;
  children: React.ReactElement;
}) {
  if (!text) return children;
  return (
    <Tooltip>
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent className="max-w-xs text-left whitespace-pre-line">
        {text}
      </TooltipContent>
    </Tooltip>
  );
}

export function DisclosureHeader({
  open,
  onToggle,
  title,
  summary,
  description,
  actions,
}: {
  open: boolean;
  onToggle: () => void;
  title: string;
  summary?: string;
  description?: string;
  actions?: React.ReactNode;
}) {
  return (
    <div className="flex items-center gap-1 px-2 py-1.5">
      <button
        type="button"
        onClick={onToggle}
        aria-expanded={open}
        aria-label={summary ? `${title} ${summary}` : title}
        className="flex min-w-0 flex-1 items-center gap-1.5 text-left"
      >
        <ChevronRight
          className={cn(
            "text-muted-foreground size-4 shrink-0 transition-transform",
            open && "rotate-90",
          )}
        />
        <WithDescription text={description}>
          <span className="truncate text-sm font-medium">{title}</span>
        </WithDescription>
        {summary ? (
          <span className="text-muted-foreground shrink-0 text-xs">
            {summary}
          </span>
        ) : null}
      </button>
      {actions}
    </div>
  );
}

import type * as React from "react";

import type { JsonFormTextInput } from "@/components/json-form/scalar-control";
import type { Schema } from "@/components/json-form/schema-model";

export interface JsonFormFieldRenderProps {
  name: string;
  sourcePath?: string;
  schema: Schema;
  required?: boolean;
  label?: string;
  textInput?: JsonFormTextInput;
  className?: string;
  depth?: number;
}

export type RenderJsonFormField = (
  props: JsonFormFieldRenderProps,
) => React.ReactNode;

"use client";

import * as React from "react";
import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import * as LabelPrimitive from "@radix-ui/react-label";
import { Slot } from "@radix-ui/react-slot";
import { CheckIcon } from "lucide-react";
import {
  Controller,
  FormProvider,
  useFormContext,
  useFormState,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from "react-hook-form";

import { cn } from "@/lib/utils";

export const Form = FormProvider;

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName;
};

const FormFieldContext = React.createContext<FormFieldContextValue | null>(
  null,
);

export function FormField<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>(props: ControllerProps<TFieldValues, TName>) {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
}

type FormItemContextValue = {
  id: string;
};

const FormItemContext = React.createContext<FormItemContextValue | null>(null);

function useFormField() {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  const { getFieldState } = useFormContext();

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>");
  }
  if (!itemContext) {
    throw new Error("useFormField should be used within <FormItem>");
  }

  const formState = useFormState({ name: fieldContext.name });
  const fieldState = getFieldState(fieldContext.name, formState);
  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
}

export function FormItem({ className, ...props }: React.ComponentProps<"div">) {
  const id = React.useId();

  return (
    <FormItemContext.Provider value={{ id }}>
      <div
        data-slot="form-item"
        className={cn("grid gap-2", className)}
        {...props}
      />
    </FormItemContext.Provider>
  );
}

export function FormLabel({
  className,
  ...props
}: React.ComponentProps<typeof LabelPrimitive.Root>) {
  const { error, formItemId } = useFormField();

  return (
    <LabelPrimitive.Root
      data-slot="form-label"
      data-error={!!error}
      className={cn("data-[error=true]:text-destructive", className)}
      htmlFor={formItemId}
      {...props}
    />
  );
}

export function FormControl(props: React.ComponentProps<typeof Slot>) {
  const { error, formItemId, formDescriptionId, formMessageId } =
    useFormField();
  const { children, ...controlProps } = props;
  const fieldProps = {
    "data-slot": "form-control",
    id: formItemId,
    "aria-describedby": error
      ? `${formDescriptionId} ${formMessageId}`
      : `${formDescriptionId}`,
    "aria-invalid": !!error,
    ...controlProps,
  };

  if (React.isValidElement(children)) {
    return React.cloneElement(
      children as React.ReactElement<Record<string, unknown>>,
      fieldProps,
    );
  }

  return <Slot {...fieldProps} />;
}

export function FormMessage({
  className,
  ...props
}: React.ComponentProps<"p">) {
  const { error, formMessageId } = useFormField();
  const body = error ? String(error.message ?? "") : props.children;

  if (!body) return null;

  return (
    <p
      data-slot="form-message"
      id={formMessageId}
      className={cn("text-destructive text-sm", className)}
      {...props}
    >
      {body}
    </p>
  );
}

export function Checkbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer border-input focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:data-[state=checked]:bg-primary size-4 shrink-0 rounded-[4px] border shadow-xs transition-shadow outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex items-center justify-center text-current transition-none"
      >
        <CheckIcon className="size-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export function Textarea({
  className,
  ...props
}: React.ComponentProps<"textarea">) {
  return (
    <textarea
      data-slot="textarea"
      className={cn(
        "border-input placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:bg-input/30 dark:aria-invalid:ring-destructive/40 flex min-h-16 w-full rounded-md border bg-transparent px-3 py-2 text-base shadow-none transition-[color,box-shadow] outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
        className,
      )}
      {...props}
    />
  );
}

export const AUTO_COLLAPSE_DEPTH = 1;
export const CARD_VIRTUALIZE_THRESHOLD = 30;
export const LONG_ARRAY_THRESHOLD = 8;

"use client";

import * as React from "react";
import { type SubmitHandler, type UseFormReturn } from "react-hook-form";

import { cn } from "@/lib/utils";
import { JsonFormArray } from "@/components/json-form/array-fields";
import { WithDescription } from "@/components/json-form/disclosure";
import type { JsonFormFieldRenderProps } from "@/components/json-form/field-renderer";
import {
  Form,
  FormControl,
