export type { JsonFormTextInput } from "@/components/json-form/scalar-control";

/**
 * A JSON-Schema-driven form built entirely on shadcn's `FormField` abstraction.
 *
 * Each schema property is rendered through `<FormField>` →
 * `<FormItem>/<FormLabel>/<FormControl>/<FormDescription>/<FormMessage>`, so it
 * inherits shadcn's react-hook-form wiring, accessibility, and error display
 * with zero bespoke styling. Objects nest, arrays repeat, and scalars map to the
 * matching control. Drop it inside your own `useForm()` instance.
 *
 * Built to scale to deep, repetitive documents (e.g. an extraction with
 * `properties[] → production[] → line_items[]`):
 *
 *  - **Lazy mount.** Nested objects and arrays are collapsible; their children
 *    are only mounted in the DOM while expanded, so a 5,000-field tree boots as
 *    a handful of summary rows.
 *  - **Table mode.** An array whose items are flat objects of scalars renders as
 *    a dense editable table (one row per item, one column per field) instead of
 *    a stack of bordered cards.
 *  - **Virtualization.** Long arrays (card *or* table mode) window their rows
 *    through local row virtualizers, so only the visible items are in the DOM.
 *  - **Isolated re-renders.** Each row subscribes to its own field state, so a
 *    keystroke in one item never re-renders its siblings.
 */

// ---------------------------------------------------------------------------
// JsonFormField — the unit of composition
// ---------------------------------------------------------------------------

export type JsonFormFieldProps = JsonFormFieldRenderProps;

export function JsonFormField({
  name,
  sourcePath,
  schema: rawSchema,
  required = false,
  label,
  textInput,
  className,
  depth = 0,
}: JsonFormFieldProps) {
  const expandedSchema = React.useMemo(
    () => expandRefs(rawSchema),
    [rawSchema],
  );
  const { schema, nullable } = unwrapNullable(expandedSchema);
  const kind = fieldKind(schema);
  const heading = labelFor(name, schema, label);
  const resolvedSourcePath = sourcePath ?? name;

  if (kind === "object") {
    return (
      <JsonFormObject
        name={name}
        sourcePath={resolvedSourcePath}
        schema={schema}
        label={heading}
        textInput={textInput}
        className={className}
        depth={depth}
        renderField={renderJsonFormField}
      />
    );
  }

  if (kind === "array") {
    return (
      <JsonFormArray
        name={name}
        sourcePath={resolvedSourcePath}
        schema={schema}
        label={heading}
        textInput={textInput}
        className={className}
        depth={depth}
        renderField={renderJsonFormField}
      />
    );
  }

  if (kind === "boolean") {
    if (nullable) {
      return (
        <SourceLinkShell sourcePath={resolvedSourcePath}>
          <FormField
            name={name}
            render={({ field }) => (
              <FormItem className={className}>
                <WithDescription text={schema.description}>
                  <FormLabel>
                    {heading}
                    {required ? (
                      <span className="text-destructive"> *</span>
                    ) : null}
                  </FormLabel>
                </WithDescription>
                <FormControl>
                  <NullableBooleanControl
                    field={field}
                    label={`${heading}${required ? " *" : ""}`}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </SourceLinkShell>
      );
    }

    return (
      <SourceLinkShell sourcePath={resolvedSourcePath}>
        <FormField
          name={name}
          render={({ field }) => (
            <FormItem className={className}>
              <WithDescription text={schema.description}>
                <FormLabel>
                  {heading}
                  {required ? (
                    <span className="text-destructive"> *</span>
                  ) : null}
                </FormLabel>
              </WithDescription>
              <FormControl>
                <BooleanControl
                  field={field}
                  label={`${heading}${required ? " *" : ""}`}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
      </SourceLinkShell>
    );
  }

  return (
    <SourceLinkShell sourcePath={resolvedSourcePath}>
      <FormField
        name={name}
        render={({ field }) => (
          <FormItem className={className}>
            <WithDescription text={schema.description}>
              <FormLabel>
                {heading}
                {required ? <span className="text-destructive"> *</span> : null}
              </FormLabel>
            </WithDescription>
            <FormControl>
              <ScalarControl
                kind={kind}
                schema={schema}
                field={field}
                textInput={textInput}
                nullable={nullable}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
    </SourceLinkShell>
  );
}

function renderJsonFormField(props: JsonFormFieldRenderProps) {
  return <JsonFormField {...props} />;
}

// ---------------------------------------------------------------------------
// JsonForm — convenience wrapper over a whole schema
// ---------------------------------------------------------------------------

export interface JsonFormProps {
  form: UseFormReturn<Record<string, unknown>>;
  schema: Schema;
  onSubmit?: SubmitHandler<Record<string, unknown>>;
  className?: string;
  /** Force plain string fields to render as single-line inputs or textareas. */
  textInput?: JsonFormTextInput;
  /**
   * Opt into field-level source linking. When set, every scalar field becomes a
   * hoverable card that reports its path and highlights when active — wire it
   * straight from a source field link.
   */
  sourceLink?: JsonFormSourceLink;
  /**
   * Source/logical paths that should start expanded. Intended for controlled
   * demos and benchmarks that need a deep virtualized body mounted immediately.
   */
  defaultOpenPaths?: readonly string[];
  /** Rendered after the fields, e.g. a submit button. */
  children?: React.ReactNode;
}

export function JsonForm({
  form,
  schema,
  onSubmit,
  className,
  textInput,
  sourceLink,
  defaultOpenPaths,
  children,
}: JsonFormProps) {
  const expandedSchema = React.useMemo(() => expandRefs(schema), [schema]);
  const usesEncodedPaths = React.useMemo(
    () => schemaNeedsJsonFormPathEncoding(expandedSchema),
    [expandedSchema],
  );
  const defaultOpenPathSet = React.useMemo(
    () =>
      defaultOpenPaths && defaultOpenPaths.length > 0
        ? new Set(defaultOpenPaths)
        : null,
    [defaultOpenPaths],
  );
  const hasEncodedInitialValuesRef = React.useRef(false);

  useKeyedMountEffect(
    joinEffectKey([expandedSchema, form, usesEncodedPaths]),
    () => {
      if (!usesEncodedPaths || hasEncodedInitialValuesRef.current) {
        return;
      }
      hasEncodedInitialValuesRef.current = true;
      form.reset(
        encodeJsonFormValue(expandedSchema, form.getValues()) as Record<
          string,
          unknown
        >,
      );
    },
  );

  const handleSubmit = React.useCallback(
    (event: React.FormEvent) => {
      if (!onSubmit) {
        event.preventDefault();
        return;
      }
      const activeElement = event.currentTarget.ownerDocument.activeElement;
      if (
        activeElement instanceof HTMLElement &&
        event.currentTarget.contains(activeElement)
      ) {
        activeElement.blur();
      }
      return form.handleSubmit((data, submitEvent) => {
        const decoded = usesEncodedPaths
          ? (decodeJsonFormValue(expandedSchema, data) as Record<
              string,
              unknown
            >)
          : data;
        return onSubmit(decoded, submitEvent);
      })(event);
    },
    [expandedSchema, form, onSubmit, usesEncodedPaths],
  );

  return (
    <JsonFormSourceLinkProvider sourceLink={sourceLink}>
      <JsonFormOpenPathsContext.Provider value={defaultOpenPathSet}>
        <Form {...form}>
          <form onSubmit={handleSubmit} className={cn("space-y-4", className)}>
            <JsonFormRootFields
              schema={expandedSchema}
              textInput={textInput}
              renderField={renderJsonFormField}
            />
            {children}
          </form>
        </Form>
      </JsonFormOpenPathsContext.Provider>
    </JsonFormSourceLinkProvider>
  );
}

"use client";

import * as React from "react";
import { useFormContext, useWatch } from "react-hook-form";

import { cn } from "@/lib/utils";
import { DisclosureHeader } from "@/components/json-form/disclosure";
import type { RenderJsonFormField } from "@/components/json-form/field-renderer";
import { AUTO_COLLAPSE_DEPTH } from "@/components/json-form/json-form-constants";
import { useJsonFormStartsOpen } from "@/components/json-form/open-paths";
import {
  dynamicPropertyEntries,
  joinJsonFormPath,
  joinJsonSourcePath,
  staticPropertyKeys,
} from "@/components/json-form/path-codec";
import type { JsonFormTextInput } from "@/components/json-form/scalar-control";
import {
  labelFor,
  schemaProperties,
  type Schema,
} from "@/components/json-form/schema-model";

export function JsonFormObject({
  name,
  sourcePath,
  schema,
  label,
  textInput,
  className,
  depth,
  renderField,
}: {
  name: string;
  sourcePath: string;
  schema: Schema;
  label: string;
  textInput?: JsonFormTextInput;
  className?: string;
  depth: number;
  renderField: RenderJsonFormField;
}) {
  const { control, getValues } = useFormContext();
  const properties = React.useMemo(() => schemaProperties(schema), [schema]);
  const required = React.useMemo(
    () => new Set(schema.required ?? []),
    [schema],
  );
  const entries = React.useMemo(() => Object.entries(properties), [properties]);
  const currentValue = useWatch({
    control,
    name,
    defaultValue: getValues(name),
  }) as unknown;
  const staticKeys = React.useMemo(() => staticPropertyKeys(schema), [schema]);
  const dynamicEntries = React.useMemo(
    () => dynamicPropertyEntries(schema, currentValue, staticKeys),
    [currentValue, schema, staticKeys],
  );
  const fieldCount = entries.length + dynamicEntries.length;
  const startsOpen = useJsonFormStartsOpen(
    sourcePath,
    depth < AUTO_COLLAPSE_DEPTH,
  );
  const [open, setOpen] = React.useState(startsOpen);

  return (
    <div className={cn("rounded-lg border", className)}>
      <DisclosureHeader
        open={open}
        onToggle={() => setOpen((o) => !o)}
        title={label}
        summary={`${fieldCount} field${fieldCount === 1 ? "" : "s"}`}
        description={schema.description}
      />
      {open ? (
        <div className="space-y-3 border-t p-3">
          {entries.map(([key, child]) =>
            typeof child === "object" ? (
              <React.Fragment key={key}>
                {renderField({
                  name: joinJsonFormPath(name, key),
                  sourcePath: joinJsonSourcePath(sourcePath, key),
                  schema: child,
                  required: required.has(key),
                  label: labelFor(key, child),
                  textInput,
                  depth: depth + 1,
                })}
              </React.Fragment>
            ) : null,
          )}
          {dynamicEntries.map(({ key, schema: child }) => (
            <React.Fragment key={key}>
              {renderField({
                name: joinJsonFormPath(name, key),
                sourcePath: joinJsonSourcePath(sourcePath, key),
                schema: child,
                label: key,
                textInput,
                depth: depth + 1,
              })}
            </React.Fragment>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function JsonFormRootFields({
  schema,
  textInput,
  renderField,
}: {
  schema: Schema;
  textInput?: JsonFormTextInput;
  renderField: RenderJsonFormField;
}) {
  const { control, getValues } = useFormContext();
  const properties = schemaProperties(schema);
  const required = new Set(schema.required ?? []);
  const entries = Object.entries(properties);
  const currentValue = useWatch({
    control,
    defaultValue: getValues(),
  }) as unknown;
  const staticKeys = React.useMemo(() => staticPropertyKeys(schema), [schema]);
  const dynamicEntries = React.useMemo(
    () => dynamicPropertyEntries(schema, currentValue, staticKeys),
    [currentValue, schema, staticKeys],
  );

  return (
    <>
      {entries.map(([key, child]) =>
        typeof child === "object" ? (
          <React.Fragment key={key}>
            {renderField({
              name: joinJsonFormPath("", key),
              sourcePath: key,
              schema: child,
              required: required.has(key),
              label: labelFor(key, child),
              textInput,
              depth: 0,
            })}
          </React.Fragment>
        ) : null,
      )}
      {dynamicEntries.map(({ key, schema: child }) => (
        <React.Fragment key={key}>
          {renderField({
            name: joinJsonFormPath("", key),
            sourcePath: key,
            schema: child,
            label: key,
            textInput,
            depth: 0,
          })}
        </React.Fragment>
      ))}
    </>
  );
}

"use client";

import * as React from "react";

export const JsonFormOpenPathsContext =
  React.createContext<ReadonlySet<string> | null>(null);

export function useJsonFormStartsOpen(sourcePath: string, fallback: boolean) {
  return (
    React.useContext(JsonFormOpenPathsContext)?.has(sourcePath) ?? fallback
  );
}

import {
  arrayItemSchemaAt,
  dynamicPropertySchemaFor,
  emptyValueFor,
  fieldKind,
  isRecordValue,
  schemaPatternProperties,
  schemaProperties,
  unwrapNullable,
  type Schema,
} from "@/components/json-form/schema-model";

export function encodeJsonFormKey(segment: string): string {
  return encodeURIComponent(segment)
    .replace(
      /[!'()*]/g,
      (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`,
    )
    .replace(
      /[.[\]'"]/g,
      (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`,
    );
}

export function decodeJsonFormKey(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

export function joinJsonFormPath(parent: string, key: string | number): string {
  const segment =
    typeof key === "number" ? String(key) : encodeJsonFormKey(key);
  return parent ? `${parent}.${segment}` : segment;
}

export function joinJsonSourcePath(
  parent: string,
  key: string | number,
): string {
  const segment = String(key);
  return parent ? `${parent}.${segment}` : segment;
}

export function staticPropertyKeys(schema: Schema): Set<string> {
  return new Set(
    Object.keys(schemaProperties(schema)).flatMap((key) => [
      key,
      encodeJsonFormKey(key),
    ]),
  );
}

export function dynamicPropertyEntries(
  schema: Schema,
  currentValue: unknown,
  staticKeys: Set<string>,
): Array<{ key: string; schema: Schema }> {
  if (!isRecordValue(currentValue)) return [];
  return Object.keys(currentValue).flatMap((key) => {
    if (staticKeys.has(key)) return [];
    const decodedKey = decodeJsonFormKey(key);
    if (staticKeys.has(decodedKey)) return [];
    const childSchema = dynamicPropertySchemaFor(schema, decodedKey);
    return childSchema ? [{ key: decodedKey, schema: childSchema }] : [];
  });
}

export function schemaNeedsJsonFormPathEncoding(schema: Schema): boolean {
  const { schema: inner } = unwrapNullable(schema);
  const kind = fieldKind(inner);
  if (kind === "object") {
    const properties = schemaProperties(inner);
    const patternProperties = schemaPatternProperties(inner);
    return (
      isRecordValue(inner.additionalProperties) ||
      Object.values(patternProperties).some(isRecordValue) ||
      Object.entries(properties).some(([key, child]) => {
        return (
          encodeJsonFormKey(key) !== key ||
          (typeof child === "object" &&
            child !== null &&
            schemaNeedsJsonFormPathEncoding(child))
        );
      })
    );
  }
  if (kind === "array" && typeof inner.items === "object" && inner.items) {
    if (Array.isArray(inner.items)) {
      return inner.items.some((item) =>
        isRecordValue(item)
          ? schemaNeedsJsonFormPathEncoding(item as Schema)
          : false,
      );
    }
    return schemaNeedsJsonFormPathEncoding(inner.items as Schema);
  }
  return false;
}

export function encodeJsonFormValue(schema: Schema, value: unknown): unknown {
  const { schema: inner } = unwrapNullable(schema);
  const kind = fieldKind(inner);

  if (kind === "array") {
    if (!Array.isArray(value)) return value;
    return value.map((item, index) =>
      encodeJsonFormValue(arrayItemSchemaAt(inner, index), item),
    );
  }

  if (kind !== "object" || !isRecordValue(value)) return value;

  const properties = schemaProperties(inner);
  const encoded: Record<string, unknown> = {};
  for (const [key, child] of Object.entries(properties)) {
    if (typeof child !== "object" || child === null) continue;
    const encodedKey = encodeJsonFormKey(key);
    const rawValue = Object.prototype.hasOwnProperty.call(value, key)
      ? value[key]
      : value[encodedKey];
    if (
      rawValue !== undefined ||
      Object.prototype.hasOwnProperty.call(value, key)
    ) {
      encoded[encodedKey] = encodeJsonFormValue(child, rawValue);
    }
  }
  const propertyKeys = new Set(Object.keys(properties));
  for (const [key, rawValue] of Object.entries(value)) {
    const decodedKey = decodeJsonFormKey(key);
    if (propertyKeys.has(key) || propertyKeys.has(decodedKey)) continue;
    const childSchema = dynamicPropertySchemaFor(inner, decodedKey);
    if (!childSchema) continue;
    encoded[encodeJsonFormKey(decodedKey)] = encodeJsonFormValue(
      childSchema,
      rawValue,
    );
  }
  return encoded;
}

export function decodeJsonFormValue(schema: Schema, value: unknown): unknown {
  const { schema: inner } = unwrapNullable(schema);
  const kind = fieldKind(inner);

  if (kind === "array") {
    if (!Array.isArray(value)) return value;
    return value.map((item, index) =>
      decodeJsonFormValue(arrayItemSchemaAt(inner, index), item),
    );
  }

  if (kind !== "object" || !isRecordValue(value)) return value;

  const properties = schemaProperties(inner);
  const decoded: Record<string, unknown> = {};
  const handledKeys = new Set<string>();
  for (const [key, child] of Object.entries(properties)) {
    if (typeof child !== "object" || child === null) continue;
    const encodedKey = encodeJsonFormKey(key);
    const hasEncoded = Object.prototype.hasOwnProperty.call(value, encodedKey);
    const rawValue = hasEncoded ? value[encodedKey] : value[key];
    handledKeys.add(encodedKey);
    handledKeys.add(key);
    if (
      rawValue !== undefined ||
      hasEncoded ||
      Object.prototype.hasOwnProperty.call(value, key)
    ) {
      decoded[key] = decodeJsonFormValue(child, rawValue);
    }
  }
  for (const [key, rawValue] of Object.entries(value)) {
    const decodedKey = decodeJsonFormKey(key);
    if (handledKeys.has(key) || handledKeys.has(decodedKey)) continue;
    const childSchema = dynamicPropertySchemaFor(inner, decodedKey);
    if (!childSchema) continue;
    decoded[decodedKey] = decodeJsonFormValue(childSchema, rawValue);
  }
  return decoded;
}

export function emptyArrayItemFormValue(schema: Schema): unknown {
  const { schema: inner, nullable } = unwrapNullable(schema);
  if (nullable) return null;
  if (fieldKind(inner) !== "object") return emptyValueFor(inner);

  const value: Record<string, unknown> = {};
  const shouldEncodeKeys = schemaNeedsJsonFormPathEncoding(inner);
  for (const [key, child] of Object.entries(schemaProperties(inner))) {
    if (typeof child === "object" && child !== null) {
      value[shouldEncodeKeys ? encodeJsonFormKey(key) : key] =
        emptyValueFor(child);
    }
  }
  return value;
}

