import {
  BooleanControl,
  NullableBooleanControl,
} from "@/components/json-form/scalar/boolean-control";
import {
  datetimeLocalInputValue,
  DateTimeScalarControl,
} from "@/components/json-form/scalar/date-time-control";
import {
  EnumControl,
  enumLabel,
  enumValueEquals,
} from "@/components/json-form/scalar/enum-control";
import {
  dataCellNumberValue,
  NumberControl,
} from "@/components/json-form/scalar/number-control";
import {
  dataCellTextValue,
  TextControl,
} from "@/components/json-form/scalar/text-control";
import type {
  ControlFieldApi,
  DateTimeControlKind,
  JsonFormTextInput,
  ScalarControlDomProps,
} from "@/components/json-form/scalar/types";
import type { FieldKind, Schema } from "@/components/json-form/schema-model";

export type {
  ControlFieldApi,
  JsonFormTextInput,
  ScalarControlDomProps,
} from "@/components/json-form/scalar/types";
export {
  BooleanControl,
  dataCellNumberValue,
  dataCellTextValue,
  datetimeLocalInputValue,
  enumLabel,
  enumValueEquals,
  NullableBooleanControl,
};

export function ScalarControl({
  kind,
  schema,
  field,
  textInput,
  compact = false,
  nullable = false,
  ...controlProps
}: {
  kind: FieldKind;
  schema: Schema;
  field: ControlFieldApi;
  textInput?: JsonFormTextInput;
  /** Dense, single-line variant for table cells. */
  compact?: boolean;
  nullable?: boolean;
} & ScalarControlDomProps) {
  if (kind === "enum") {
    return (
      <EnumControl
        {...controlProps}
        schema={schema}
        field={field}
        compact={compact}
        nullable={nullable}
      />
    );
  }

  if (kind === "number" || kind === "integer") {
    return (
      <NumberControl
        {...controlProps}
        kind={kind}
        field={field}
        compact={compact}
        nullable={nullable}
      />
    );
  }

  if (
    schema.format === "date" ||
    schema.format === "time" ||
    schema.format === "date-time"
  ) {
    return (
      <DateTimeScalarControl
        {...controlProps}
        kind={schema.format as DateTimeControlKind}
        field={field}
        compact={compact}
        nullable={nullable}
      />
    );
  }

  return (
    <TextControl
      {...controlProps}
      schema={schema}
      field={field}
      textInput={textInput}
      compact={compact}
      nullable={nullable}
    />
  );
}

"use client";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/json-form/form-primitives";
import { NULL_SELECT_VALUE } from "@/components/json-form/scalar/enum-control";
import {
  type ControlFieldApi,
  type ScalarControlDomProps,
} from "@/components/json-form/scalar/types";

export function BooleanControl({
  field,
  label,
}: {
  field: ControlFieldApi;
  label: string;
}) {
  return (
    <Checkbox
      checked={Boolean(field.value)}
      aria-label={label}
      onCheckedChange={(value) => field.onChange(value === true)}
      onBlur={field.onBlur}
    />
  );
}

export function NullableBooleanControl({
  field,
  label,
  ...controlProps
}: {
  field: ControlFieldApi;
  label: string;
} & ScalarControlDomProps) {
  const selectValue =
    field.value === true
      ? "true"
      : field.value === false
        ? "false"
        : NULL_SELECT_VALUE;
  const displayValue =
    field.value === true
      ? "True"
      : field.value === false
        ? "False"
        : "No value";

  return (
    <Select
      value={selectValue}
      onValueChange={(value) => {
        if (value === "true") {
          field.onChange(true);
          return;
        }
        if (value === "false") {
          field.onChange(false);
          return;
        }
        field.onChange(null);
      }}
    >
      <SelectTrigger {...controlProps} aria-label={label}>
        <SelectValue placeholder="Select...">{displayValue}</SelectValue>
      </SelectTrigger>
      <SelectContent>
        <SelectItem value={NULL_SELECT_VALUE}>No value</SelectItem>
        <SelectItem value="true">True</SelectItem>
        <SelectItem value="false">False</SelectItem>
      </SelectContent>
    </Select>
  );
}

